import Foundation

struct RunicCrucibleAetherBrewGameEngine {
    private(set) var RunicCrucibleAetherBrewLevel: RunicCrucibleAetherBrewLevelDefinition
    private(set) var RunicCrucibleAetherBrewState: RunicCrucibleAetherBrewGameState
    private var RunicCrucibleAetherBrewHistory: [RunicCrucibleAetherBrewGameState] = []
    init(RunicCrucibleAetherBrewLevel: RunicCrucibleAetherBrewLevelDefinition) { self.RunicCrucibleAetherBrewLevel = RunicCrucibleAetherBrewLevel; RunicCrucibleAetherBrewState = .init(RunicCrucibleAetherBrewVials: RunicCrucibleAetherBrewLevel.RunicCrucibleAetherBrewVials.map { .init(RunicCrucibleAetherBrewTypes: $0, RunicCrucibleAetherBrewCapacity: RunicCrucibleAetherBrewLevel.RunicCrucibleAetherBrewCapacity) }, RunicCrucibleAetherBrewMoves: 0, RunicCrucibleAetherBrewHintsUsed: 0, RunicCrucibleAetherBrewIsWon: false) }
    init(RunicCrucibleAetherBrewLevel: RunicCrucibleAetherBrewLevelDefinition, RunicCrucibleAetherBrewState: RunicCrucibleAetherBrewGameState) { self.RunicCrucibleAetherBrewLevel = RunicCrucibleAetherBrewLevel; self.RunicCrucibleAetherBrewState = RunicCrucibleAetherBrewState }
    func RunicCrucibleAetherBrewRejection(for RunicCrucibleAetherBrewMove: RunicCrucibleAetherBrewMove) -> RunicCrucibleAetherBrewMoveRejection? {
        let RunicCrucibleAetherBrewSourceIndex = RunicCrucibleAetherBrewMove.RunicCrucibleAetherBrewSource
        let RunicCrucibleAetherBrewDestinationIndex = RunicCrucibleAetherBrewMove.RunicCrucibleAetherBrewDestination
        guard RunicCrucibleAetherBrewSourceIndex != RunicCrucibleAetherBrewDestinationIndex else { return .RunicCrucibleAetherBrewSameVial }
        guard RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials.indices.contains(RunicCrucibleAetherBrewSourceIndex), RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials.indices.contains(RunicCrucibleAetherBrewDestinationIndex) else { return .RunicCrucibleAetherBrewEssenceMismatch }
        let RunicCrucibleAetherBrewSource = RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewSourceIndex]
        let RunicCrucibleAetherBrewDestination = RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewDestinationIndex]
        guard !RunicCrucibleAetherBrewSource.RunicCrucibleAetherBrewLayers.isEmpty else { return .RunicCrucibleAetherBrewEmptySource }
        guard RunicCrucibleAetherBrewSource.RunicCrucibleAetherBrewFrozenTurns == 0, RunicCrucibleAetherBrewDestination.RunicCrucibleAetherBrewFrozenTurns == 0 else { return .RunicCrucibleAetherBrewFrozen }
        guard RunicCrucibleAetherBrewDestination.RunicCrucibleAetherBrewLayers.count < RunicCrucibleAetherBrewDestination.RunicCrucibleAetherBrewCapacity else { return .RunicCrucibleAetherBrewFullDestination }
        guard let RunicCrucibleAetherBrewTarget = RunicCrucibleAetherBrewDestination.RunicCrucibleAetherBrewLayers.last, let RunicCrucibleAetherBrewTop = RunicCrucibleAetherBrewSource.RunicCrucibleAetherBrewLayers.last else { return nil }
        let RunicCrucibleAetherBrewPair = Set([RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType, RunicCrucibleAetherBrewTarget.RunicCrucibleAetherBrewType])
        if RunicCrucibleAetherBrewLevel.RunicCrucibleAetherBrewRules.contains(.polarity), RunicCrucibleAetherBrewPair == Set([.light, .shadow]) { return .RunicCrucibleAetherBrewPolarity }
        return RunicCrucibleAetherBrewCanMove(RunicCrucibleAetherBrewMove) ? nil : .RunicCrucibleAetherBrewEssenceMismatch
    }
    func RunicCrucibleAetherBrewCanMove(_ RunicCrucibleAetherBrewMove: RunicCrucibleAetherBrewMove) -> Bool {
        let RunicCrucibleAetherBrewSourceIndex = RunicCrucibleAetherBrewMove.RunicCrucibleAetherBrewSource, RunicCrucibleAetherBrewDestinationIndex = RunicCrucibleAetherBrewMove.RunicCrucibleAetherBrewDestination
        guard RunicCrucibleAetherBrewSourceIndex != RunicCrucibleAetherBrewDestinationIndex, RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials.indices.contains(RunicCrucibleAetherBrewSourceIndex), RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials.indices.contains(RunicCrucibleAetherBrewDestinationIndex) else { return false }
        let RunicCrucibleAetherBrewSource = RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewSourceIndex], RunicCrucibleAetherBrewDestination = RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewDestinationIndex]
        guard RunicCrucibleAetherBrewSource.RunicCrucibleAetherBrewFrozenTurns == 0, RunicCrucibleAetherBrewDestination.RunicCrucibleAetherBrewFrozenTurns == 0, let RunicCrucibleAetherBrewTop = RunicCrucibleAetherBrewSource.RunicCrucibleAetherBrewLayers.last, RunicCrucibleAetherBrewDestination.RunicCrucibleAetherBrewLayers.count < RunicCrucibleAetherBrewDestination.RunicCrucibleAetherBrewCapacity else { return false }
        guard let RunicCrucibleAetherBrewTarget = RunicCrucibleAetherBrewDestination.RunicCrucibleAetherBrewLayers.last else { return true }
        let RunicCrucibleAetherBrewPair = Set([RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType, RunicCrucibleAetherBrewTarget.RunicCrucibleAetherBrewType])
        if RunicCrucibleAetherBrewLevel.RunicCrucibleAetherBrewRules.contains(.polarity), RunicCrucibleAetherBrewPair == Set([.light, .shadow]) { return false }
        if RunicCrucibleAetherBrewLevel.RunicCrucibleAetherBrewRules.contains(.nature), RunicCrucibleAetherBrewPair == Set([.nature, .water]) { return true }
        if RunicCrucibleAetherBrewLevel.RunicCrucibleAetherBrewRules.contains(.void), RunicCrucibleAetherBrewTarget.RunicCrucibleAetherBrewType == .void, !RunicCrucibleAetherBrewDestination.RunicCrucibleAetherBrewVoidIsSpent { return true }
        return RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType == RunicCrucibleAetherBrewTarget.RunicCrucibleAetherBrewType || RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType == .aether
    }
    func RunicCrucibleAetherBrewTransferPlan(for RunicCrucibleAetherBrewMove: RunicCrucibleAetherBrewMove) -> RunicCrucibleAetherBrewTransferPlan? {
        guard RunicCrucibleAetherBrewCanMove(RunicCrucibleAetherBrewMove) else { return nil }
        let RunicCrucibleAetherBrewSource = RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewMove.RunicCrucibleAetherBrewSource]
        let RunicCrucibleAetherBrewDestination = RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewMove.RunicCrucibleAetherBrewDestination]
        guard let RunicCrucibleAetherBrewTop = RunicCrucibleAetherBrewSource.RunicCrucibleAetherBrewLayers.last else { return nil }
        let RunicCrucibleAetherBrewTopGroupCount = RunicCrucibleAetherBrewSource.RunicCrucibleAetherBrewLayers.reversed().prefix { $0.RunicCrucibleAetherBrewType == RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType && $0.RunicCrucibleAetherBrewIsEmpowered == RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewIsEmpowered }.count
        let RunicCrucibleAetherBrewFreeSpace = RunicCrucibleAetherBrewDestination.RunicCrucibleAetherBrewCapacity - RunicCrucibleAetherBrewDestination.RunicCrucibleAetherBrewLayers.count
        let RunicCrucibleAetherBrewTargetType = RunicCrucibleAetherBrewDestination.RunicCrucibleAetherBrewLayers.last?.RunicCrucibleAetherBrewType
        let RunicCrucibleAetherBrewSpecialReaction = (RunicCrucibleAetherBrewLevel.RunicCrucibleAetherBrewRules.contains(.frost) && RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType == .frost && RunicCrucibleAetherBrewTargetType != nil && RunicCrucibleAetherBrewTargetType != .frost)
            || (RunicCrucibleAetherBrewLevel.RunicCrucibleAetherBrewRules.contains(.nature) && Set([RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType, RunicCrucibleAetherBrewTargetType].compactMap { $0 }) == Set([.nature, .water]))
            || (RunicCrucibleAetherBrewLevel.RunicCrucibleAetherBrewRules.contains(.aether) && RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType == .aether && RunicCrucibleAetherBrewTargetType != nil && RunicCrucibleAetherBrewTargetType != .aether)
            || (RunicCrucibleAetherBrewLevel.RunicCrucibleAetherBrewRules.contains(.void) && RunicCrucibleAetherBrewTargetType == .void && RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType != .void && !RunicCrucibleAetherBrewDestination.RunicCrucibleAetherBrewVoidIsSpent)
        return .init(RunicCrucibleAetherBrewSource: RunicCrucibleAetherBrewMove.RunicCrucibleAetherBrewSource, RunicCrucibleAetherBrewDestination: RunicCrucibleAetherBrewMove.RunicCrucibleAetherBrewDestination, RunicCrucibleAetherBrewType: RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType, RunicCrucibleAetherBrewCount: RunicCrucibleAetherBrewSpecialReaction ? 1 : min(RunicCrucibleAetherBrewTopGroupCount, RunicCrucibleAetherBrewFreeSpace))
    }
    mutating func RunicCrucibleAetherBrewApply(_ RunicCrucibleAetherBrewMove: RunicCrucibleAetherBrewMove) -> RunicCrucibleAetherBrewMoveResult? {
        guard let RunicCrucibleAetherBrewPlan = RunicCrucibleAetherBrewTransferPlan(for: RunicCrucibleAetherBrewMove) else { return nil }; RunicCrucibleAetherBrewHistory.append(RunicCrucibleAetherBrewState)
        for RunicCrucibleAetherBrewIndex in RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials.indices where RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewIndex].RunicCrucibleAetherBrewFrozenTurns > 0 { RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewIndex].RunicCrucibleAetherBrewFrozenTurns -= 1 }
        let RunicCrucibleAetherBrewSource = RunicCrucibleAetherBrewMove.RunicCrucibleAetherBrewSource, RunicCrucibleAetherBrewDestination = RunicCrucibleAetherBrewMove.RunicCrucibleAetherBrewDestination
        let RunicCrucibleAetherBrewStartIndex = RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewSource].RunicCrucibleAetherBrewLayers.count - RunicCrucibleAetherBrewPlan.RunicCrucibleAetherBrewCount
        let RunicCrucibleAetherBrewLayers = Array(RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewSource].RunicCrucibleAetherBrewLayers[RunicCrucibleAetherBrewStartIndex...])
        RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewSource].RunicCrucibleAetherBrewLayers.removeLast(RunicCrucibleAetherBrewPlan.RunicCrucibleAetherBrewCount)
        RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewDestination].RunicCrucibleAetherBrewLayers.append(contentsOf: RunicCrucibleAetherBrewLayers)
        var RunicCrucibleAetherBrewReactions = [RunicCrucibleAetherBrewReaction(RunicCrucibleAetherBrewKind: .poured, RunicCrucibleAetherBrewVialIndex: RunicCrucibleAetherBrewDestination, RunicCrucibleAetherBrewType: RunicCrucibleAetherBrewPlan.RunicCrucibleAetherBrewType)]
        RunicCrucibleAetherBrewResolve(RunicCrucibleAetherBrewIndex: RunicCrucibleAetherBrewDestination, RunicCrucibleAetherBrewReactions: &RunicCrucibleAetherBrewReactions)
        RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewMoves += 1; RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewIsWon = RunicCrucibleAetherBrewCheckWin()
        return .init(RunicCrucibleAetherBrewState: RunicCrucibleAetherBrewState, RunicCrucibleAetherBrewReactions: RunicCrucibleAetherBrewReactions, RunicCrucibleAetherBrewTransferPlan: RunicCrucibleAetherBrewPlan, RunicCrucibleAetherBrewSourceVial: RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewSource], RunicCrucibleAetherBrewDestinationVial: RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewDestination])
    }
    private mutating func RunicCrucibleAetherBrewResolve(RunicCrucibleAetherBrewIndex: Int, RunicCrucibleAetherBrewReactions: inout [RunicCrucibleAetherBrewReaction]) {
        var RunicCrucibleAetherBrewVial = RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewIndex]; guard RunicCrucibleAetherBrewVial.RunicCrucibleAetherBrewLayers.count > 1 else { return }
        let RunicCrucibleAetherBrewTop = RunicCrucibleAetherBrewVial.RunicCrucibleAetherBrewLayers.last!, RunicCrucibleAetherBrewBelow = RunicCrucibleAetherBrewVial.RunicCrucibleAetherBrewLayers[RunicCrucibleAetherBrewVial.RunicCrucibleAetherBrewLayers.count - 2]
        if RunicCrucibleAetherBrewLevel.RunicCrucibleAetherBrewRules.contains(.frost), RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType == .frost, RunicCrucibleAetherBrewBelow.RunicCrucibleAetherBrewType != .frost { RunicCrucibleAetherBrewVial.RunicCrucibleAetherBrewFrozenTurns = 1; RunicCrucibleAetherBrewReactions.append(.init(RunicCrucibleAetherBrewKind: .frozen, RunicCrucibleAetherBrewVialIndex: RunicCrucibleAetherBrewIndex, RunicCrucibleAetherBrewType: .frost)) }
        if RunicCrucibleAetherBrewLevel.RunicCrucibleAetherBrewRules.contains(.nature), Set([RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType, RunicCrucibleAetherBrewBelow.RunicCrucibleAetherBrewType]) == Set([.nature, .water]) { RunicCrucibleAetherBrewVial.RunicCrucibleAetherBrewLayers.removeLast(2); RunicCrucibleAetherBrewVial.RunicCrucibleAetherBrewLayers.append(.init(RunicCrucibleAetherBrewType: .nature, RunicCrucibleAetherBrewIsEmpowered: true)); RunicCrucibleAetherBrewReactions.append(.init(RunicCrucibleAetherBrewKind: .empowered, RunicCrucibleAetherBrewVialIndex: RunicCrucibleAetherBrewIndex, RunicCrucibleAetherBrewType: .nature)) }
        if RunicCrucibleAetherBrewLevel.RunicCrucibleAetherBrewRules.contains(.aether), RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType == .aether, RunicCrucibleAetherBrewBelow.RunicCrucibleAetherBrewType != .aether { RunicCrucibleAetherBrewVial.RunicCrucibleAetherBrewLayers[RunicCrucibleAetherBrewVial.RunicCrucibleAetherBrewLayers.count - 1].RunicCrucibleAetherBrewType = RunicCrucibleAetherBrewBelow.RunicCrucibleAetherBrewType; RunicCrucibleAetherBrewReactions.append(.init(RunicCrucibleAetherBrewKind: .copied, RunicCrucibleAetherBrewVialIndex: RunicCrucibleAetherBrewIndex, RunicCrucibleAetherBrewType: RunicCrucibleAetherBrewBelow.RunicCrucibleAetherBrewType)) }
        if RunicCrucibleAetherBrewLevel.RunicCrucibleAetherBrewRules.contains(.void), RunicCrucibleAetherBrewBelow.RunicCrucibleAetherBrewType == .void, RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType != .void, !RunicCrucibleAetherBrewVial.RunicCrucibleAetherBrewVoidIsSpent { RunicCrucibleAetherBrewVial.RunicCrucibleAetherBrewLayers.removeLast(); RunicCrucibleAetherBrewVial.RunicCrucibleAetherBrewVoidIsSpent = true; RunicCrucibleAetherBrewReactions.append(.init(RunicCrucibleAetherBrewKind: .absorbed, RunicCrucibleAetherBrewVialIndex: RunicCrucibleAetherBrewIndex, RunicCrucibleAetherBrewType: RunicCrucibleAetherBrewTop.RunicCrucibleAetherBrewType)) }
        RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials[RunicCrucibleAetherBrewIndex] = RunicCrucibleAetherBrewVial
    }
    mutating func RunicCrucibleAetherBrewUndo() -> RunicCrucibleAetherBrewGameState? { guard let RunicCrucibleAetherBrewPrevious = RunicCrucibleAetherBrewHistory.popLast() else { return nil }; RunicCrucibleAetherBrewState = RunicCrucibleAetherBrewPrevious; return RunicCrucibleAetherBrewState }
    mutating func RunicCrucibleAetherBrewRestart() { self = .init(RunicCrucibleAetherBrewLevel: RunicCrucibleAetherBrewLevel) }
    func RunicCrucibleAetherBrewHint() -> RunicCrucibleAetherBrewMove? { for RunicCrucibleAetherBrewSource in RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials.indices { for RunicCrucibleAetherBrewDestination in RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials.indices { let RunicCrucibleAetherBrewMove = RunicCrucibleAetherBrewMove(RunicCrucibleAetherBrewSource: RunicCrucibleAetherBrewSource, RunicCrucibleAetherBrewDestination: RunicCrucibleAetherBrewDestination); if RunicCrucibleAetherBrewCanMove(RunicCrucibleAetherBrewMove) { return RunicCrucibleAetherBrewMove } } }; return nil }
    func RunicCrucibleAetherBrewHasMoves() -> Bool { RunicCrucibleAetherBrewHint() != nil }
    func RunicCrucibleAetherBrewCheckWin() -> Bool {
        guard RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewMoves > 0 else { return false }
        let RunicCrucibleAetherBrewNonemptyVials = RunicCrucibleAetherBrewState.RunicCrucibleAetherBrewVials.filter { !$0.RunicCrucibleAetherBrewLayers.isEmpty }
        guard RunicCrucibleAetherBrewNonemptyVials.allSatisfy({ Set($0.RunicCrucibleAetherBrewLayers.map(\.RunicCrucibleAetherBrewType)).count == 1 }) else { return false }
        let RunicCrucibleAetherBrewPartialVials = RunicCrucibleAetherBrewNonemptyVials.filter { $0.RunicCrucibleAetherBrewLayers.count < $0.RunicCrucibleAetherBrewCapacity }
        let RunicCrucibleAetherBrewPartialTypes = RunicCrucibleAetherBrewPartialVials.compactMap { $0.RunicCrucibleAetherBrewLayers.last?.RunicCrucibleAetherBrewType }
        return Set(RunicCrucibleAetherBrewPartialTypes).count == RunicCrucibleAetherBrewPartialTypes.count
    }
}
